import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第77章 那条巷子","description":"","frontmatter":{},"headers":[],"relativePath":"第77章_那条巷子.md","filePath":"第77章_那条巷子.md"}'),o={name:"第77章_那条巷子.md"};function r(n,p,s,c,i,d){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第77章-那条巷子" tabindex="-1">第77章 那条巷子 <a class="header-anchor" href="#第77章-那条巷子" aria-label="Permalink to &quot;第77章 那条巷子&quot;">​</a></h1><p>大二寒假，我去了她那个城市。</p><p>她不知道。</p><p>还有一件事我后来才想明白。</p><p>她那年三月跟我定的那句，是“每年三月去站一下”。</p><p>我一月就去了。</p><p>我提前了两个月。</p><p>我那时候以为这只是早一点。</p><p>后来我看出来，这不是早一点。</p><p>这是我把一个她定的日子，换成了一个我想去的日子。</p><p>她定的三月，是她那边开学前，天气好，街上有人。</p><p>我选的一月，是过年，街上没人，锁着的卷帘门一排一排。</p><p>我要的就是那个没人。</p><p>我买的是硬座，三十七个小时，因为卧铺贵一百四。</p><p>我买票那天在窗口前站了很久。</p><p>那个卖票的人问我，去几天。</p><p>我说，当天回。</p><p>他说，当天回你买硬座。</p><p>我说，嗯。</p><p>他没再说话，把票递出来。</p><p>我那天出门前跟我妈说我去同学家过年。</p><p>我妈说，哪个同学。</p><p>我说，就那个。</p><p>我妈看了我一会儿，把两百块塞我兜里。</p><p>她说，你别省着吃。</p><p>我下车是她那边早上六点。</p><p>我在车站边上坐了两个钟头，等到天全亮。</p><p>我那时候心里没有一个具体的计划。</p><p>我要干什么，我不知道。</p><p>我就是想走一趟她走过的那条街。</p><p>那条街我早就背下来了。</p><p>一个超市，一个银行，一家奶茶店，奶茶店旁边有一棵很歪的树。</p><p>我七点半走到那条街上。</p><p>先是超市。超市在换季，门口挂了一排拖鞋。</p><p>然后是银行。银行还没开门，台阶上蹲着两个人等。</p><p>然后是奶茶店。</p><p>奶茶店开着，招牌换了。</p><p>原来那个牌子是圆的，粉边，她跟我讲过一次，她说那个牌子晚上亮起来像个灯泡。</p><p>现在换成了一个方的，白底，红字。</p><p>我站在那里看了很久。</p><p>那个招牌不是我的问题。</p><p>我知道这不是她的错，也不是那个店的错。</p><p>可是那一刻我心里有一种很没道理的感觉，像有人在我面前把一样东西也删掉了。</p><p>那棵树在。</p><p>歪得很厉害，往街心那边倒，树底下堆了一堆煤渣。</p><p>树上有一道很旧的、被人用刀刻的痕迹。</p><p>我凑过去看。</p><p>刻的是一个字，看不出来了，只剩笔画的沟。</p><p>我那时候想，是不是她刻的。</p><p>我当然没法知道。</p><p>我在那棵树底下站了大概四分钟。</p><p>然后我往她家那边走。</p><p>她家那个小区我打听过，从那头数第三个门。</p><p>我不知道是几楼。</p><p>她说过一个数字，我记成另一个了。</p><p>我在楼下站着，看见单元门口有一排牛奶箱，有一格的门是坏的，用胶带粘着。</p><p>我那时候身上有一样东西。</p><p>那是一张纸。</p><p>我从学校带出来的，叠成四折，放在兵袋最里面那一格。</p><p>我在火车上画的。</p><p>画的是一个窗。</p><p>窗开着，右边一小块歪的东西，是窗帘。</p><p>我不会画。</p><p>我画了十几遍，最后这一张是最像的。</p><p>我为什么画这个。</p><p>因为高一那次在书店，她翻到那样一页，她说她想进去站一会儿。</p><p>我要是想让她知道我去过，我就得写字。</p><p>我要是写字，她就要回答。</p><p>她一回答，她就得跟她妈说清楚我是谁。</p><p>所以我画了一个窗。</p><p>她一看就知道是谁画的。</p><p>别人一看，会以为是小孩玩的。</p><p>我把那张纸对折了一下，找了一根绳。</p><p>我从包里翻出来一根鞋带。</p><p>我把鞋带穿过门把手那个缝，把纸压在绳里，打了个结。</p><p>那个门是那种老式铁门，门把手上有个洞。</p><p>我挂完了，退后两步看。</p><p>风很大，那张纸在门把手上翻了一下。</p><p>我站在那里，忽然想到一件事。</p><p>我这一辈子做过的所有事里，这一件最不像我。</p><p>我没有告诉她，我没有跟她商量，我甚至没有在她面前。</p><p>我把一样东西挂在一个她可能根本不会看见的地方，然后我就走了。</p><p>我在她那个城市待了六个钟头。</p><p>我在一个小面馆吃了一份面。</p><p>面很咸。</p><p>我坐在那儿把我这一天在心里过了一遍，我想看看我到底要什么。</p><p>我要的是：她哪天路过那条街，看一眼那扇门。</p><p>我要的是她那一眼里面有一个&quot;有人来过&quot;。</p><p>我不要她来找我。</p><p>下午两点我走了。</p><p>回去又是硬座。</p><p>那三天在车上，我一句话也没跟她说。</p><p>她那天上线过，跟我讲了她的展，讲了她的猫。</p><p>我说，我今天在同学家。</p><p>她说，你同学在哪儿。</p><p>我说，不远。</p><p>她说，你今年说话这么短。</p><p>我说，我在外面，手机快没电。</p><p>那一句我撒了。</p><p>我当时身上还有百分之六十的电。</p><p>我不讲这件事的原因很简单。</p><p>我不知道讲了以后，她是高兴还是害怕。</p><p>而这两样里面，有一样会让她第二天没法上课。</p><p>三个月以后是四月。</p><p>有一天她忽然发了一句。</p><p>她说，我今天想起来一件事。</p><p>我说，什么。</p><p>她说，过年的时候我家门上有人挂了一张纸。</p><p>我说，什么样的纸。</p><p>她说，画了一个窗。</p><p>她说，歪的。</p><p>我坐在那儿，手里那支笔掉在桌上。</p><p>她说，我妈说是小孩挂的，她说风把它吹到那儿，也不知道是谁家的孩子。</p><p>她说，我妈把它收了。</p><p>我说，收了干什么。</p><p>她说，她压在鞋柜上了。</p><p>她说，前两天我找钥匙，我看见那张纸还在。</p><p>她说，我今天要走了，我把它带上了。</p><p>我说，你带它干什么。</p><p>她说，我不知道。</p><p>她说，我就是觉得，画这个东西的人，画得挺费劲的。</p><p>她说，那个人一定画了很多遍。</p><p>我看这几行，很久没动。</p><p>然后我打了一句：你留着吧。</p><p>她说，嗯。</p><p>我说，你要是不想要，你就扔。</p><p>她说，我不扔。</p><p>她说，我这个人我这一辈子，别人给我的东西我都扔了。</p><p>她说，这一张我不扔。</p><p>我说，为什么。</p><p>她说，因为它不是一个礼。</p><p>她说，它是一个人在一个风很大的早上，站在一扇铁门前面，把一样东西系上去。</p><p>她说，我拿这个怎么扔。</p><p>我说，你别多想。</p><p>她说，你放心，我什么都没多想。</p><p>她说，我就当我这边有人路过。</p><p>那天晚上我下线之前，在本子上写了一行。</p><p>我写：操作规程第三条，不要在她不知道的地方替她做决定。</p><p>我写：我违反了。</p><p>我写：她没有发现是我。</p>',140)])])}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
